def transform(grid):
    g = [row[:] for row in grid]
    from collections import Counter, defaultdict
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = defaultdict(list)
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != bg:
                points[v].append((r, c))

    # Extend each same-color diagonal sequence from its two ends.
    for color, positions in points.items():
        positions = set(positions)
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in list(positions):
                if (r + dr, c + dc) not in positions:
                    continue
                a, b = r, c
                while (0 <= a - dr < len(g) and 0 <= b - dc < len(g[0])
                       and g[a - dr][b - dc] == bg):
                    a -= dr
                    b -= dc
                    g[a][b] = color
                a, b = r + dr, c + dc
                while (0 <= a + dr < len(g) and 0 <= b + dc < len(g[0])
                       and g[a + dr][b + dc] == bg):
                    a += dr
                    b += dc
                    g[a][b] = color
    return g
